#include <vector>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int numberOfPaths(int n, std::vector<std::vector<int>>& corridors) {
        std::vector<std::unordered_set<int>> adj(n + 1);
        for (auto& edge : corridors) {
            int u = edge[0], v = edge[1];
            if (u > v) std::swap(u, v);
            adj[u].insert(v);
        }

        int count = 0;
        for (int u = 1; u <= n; ++u) {
            for (int v : adj[u]) {
                for (int w : adj[v]) {
                    if (adj[u].count(w)) {
                        count++;
                    }
                }
            }
        }
        return count;
    }
};

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int numberOfPaths(int n, int[][] corridors) {
        Set<Integer>[] adj = new HashSet[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new HashSet<>();

        for (int[] edge : corridors) {
            int u = edge[0], v = edge[1];
            if (u > v) {
                int t = u; u = v; v = t;
            }
            adj[u].add(v);
        }

        int count = 0;
        for (int u = 1; u <= n; u++) {
            for (int v : adj[u]) {
                for (int w : adj[v]) {
                    if (adj[u].contains(w)) {
                        count++;
                    }
                }
            }
        }
        return count;
    }
}

