var numberOfPaths = function(n, corridors) {
    const adj = Array.from({ length: n + 1 }, () => new Set());
    for (let [u, v] of corridors) {
        if (u > v) {
            const t = u; u = v; v = t;
        }
        adj[u].add(v);
    }

    let count = 0;
    for (let u = 1; u <= n; u++) {
        for (const v of adj[u]) {
            for (const w of adj[v]) {
                if (adj[u].has(w)) {
                    count++;
                }
            }
        }
    }
    return count;
};
